import { GoogleGenAI } from "@google/genai";
import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json());

  // Healthcheck endpoint
  app.get("/api/health", (_req, res) => {
    res.json({ status: "ok", appName: "منصة بقية الله الأعظم التعليمية" });
  });

  // Gemini AI Tutor / Teacher Assistant Endpoint
  app.post("/api/ai-assistant", async (req, res) => {
    try {
      const { prompt, mode, userRole } = req.body;
      const apiKey = process.env.GEMINI_API_KEY;

      if (!apiKey) {
        return res.status(400).json({
          text: "ملاحظة: يمكنك الاستفادة من المساعد الذكي عند ضبط مفتاح GEMINI_API_KEY في لوحة أسرار البيئة. حالياً هذه إجابة توضيحية تجريبية."
        });
      }

      const ai = new GoogleGenAI({ apiKey });

      let systemInstruction = `أنت المساعد التعليمي الذكي الخبير المدمج في 'منصة بقية الله الأعظم التعليمية'.
تساعد المعلمين والطلاب باللغة العربية السليمة والأسلوب التعليمي المشجع والرصين.
اقتصر في الإجابات على الشرح التعليمي المبسط، حل المسائل، إعداد أسئلة الاختبارات التفاعلية، وصياغة الملاحظات التشجيعية.`;

      if (mode === 'quiz_generator') {
        systemInstruction += `\nوظيفتك توليد أسئلة اختبار تفاعلية من نوع اختيار من متعدد وصحيح/خطأ مع الشرح والخيارات وتحديد الإجابة الصحيحة.`;
      } else if (mode === 'explain_concept') {
        systemInstruction += `\nوظيفتك تبسيط وفهم الفاهيم العلمية المعقدة بأسلوب النقاط والأمثلة المباشرة.`;
      }

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: `${systemInstruction}\n\n[دور المستخدم: ${userRole || 'طالب'}]\nالطلب: ${prompt}`,
      });

      res.json({ text: response.text || "لم أتمكن من الحصول على الإجابة المناسبة." });
    } catch (err: any) {
      console.error("Gemini API Error:", err);
      res.status(500).json({
        text: `حدث خطأ أثناء التواصل مع المساعد الذكي: ${err?.message || 'خطأ غير معروف'}`
      });
    }
  });

  // Vite development middleware vs production static bundle
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (_req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server started on http://0.0.0.0:${PORT}`);
  });
}

startServer();
